import{_ as t,o as a,c as r,a5 as n}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"HJ92 在字符串中找出连续最长的数字串","description":"中等 通过率：34.08% 时间限制：1秒 空间限制：32M 知识点 字符串 模拟 描述 输入一个字符串，返回其最长的数字子串，以及其长度。若有多个最长的数字子串，则将它们全部输出（按原字符串的相对位置） 本题含有多组样例输入。 数据范围：字符串长度 1≤�≤200 1≤ n ≤。","frontmatter":{"title":"HJ92 在字符串中找出连续最长的数字串","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"中等 通过率：34.08% 时间限制：1秒 空间限制：32M 知识点 字符串 模拟 描述 输入一个字符串，返回其最长的数字子串，以及其长度。若有多个最长的数字子串，则将它们全部输出（按原字符串的相对位置） 本题含有多组样例输入。 数据范围：字符串长度 1≤�≤200 1≤ n ≤。","sidebarWeight":67,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为简单[31个]/HJ92 在字符串中找出连续最长的数字串.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ92 在字符串中找出连续最长的数字串.md","filePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ92 在字符串中找出连续最长的数字串.md"}'),s={name:"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ92 在字符串中找出连续最长的数字串.md"};function o(l,e,_,i,p,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<div><h1 id="hj92-在字符串中找出连续最长的数字串" tabindex="-1">HJ92 在字符串中找出连续最长的数字串 <a class="header-anchor" href="#hj92-在字符串中找出连续最长的数字串" aria-label="Permalink to &quot;HJ92 在字符串中找出连续最长的数字串&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ92 在字符串中找出连续最长的数字串”的核心思路，并能把它用于实际开发或面试表达。 中等 通过率：34.08% 时间限制：1秒 空间限制：32M 知识点==字符串====模拟== <strong>描述</strong> 输入一个字符串，返回其最长的数字子串，以及其长度。若有多个最长的数字子串，则将它们全部输出（按原字符串的相对位置） 本题含有多组样例输入。</p></blockquote><p>数据范围：字符串长度 1≤�≤200 1≤<em>n</em>≤200 ， 保证每组输入都至少含有一个数字 <strong>输入描述：</strong> 输入一个字符串。1&lt;=len(字符串)&lt;=200 <strong>输出描述：</strong> 输出字符串中最长的数字字符串和它的长度，中间用逗号间隔。如果有相同长度的串，则要一块儿输出（中间不要输出空格）。 <strong>示例1</strong> 输入： abcd12345ed125ss123058789a8a72a6a5yy98y65ee1r2 ==复制== 输出： 123058789,9729865,2 ==复制== 说明： 样例一最长的数字子串为123058789，长度为9样例二最长的数字子有72,98,65，长度都为2</p><p>要解决这个问题，我们可以使用一个简单的扫描线算法。我们遍历字符串，当遇到数字时，我们就开始计算这个数字子串的长度，直到遇到非数字字符为止。同时，我们需要跟踪当前最长的数字子串的长度，以及对应的子串本身。如果遇到另一个长度相同的数字子串，我们就将其添加到结果列表中。最后，我们输出所有最长的数字子串以及它们的长度。</p><p>以下是实现该算法的Python代码： while True: try: s = input() max_length = 0 # 最长数字子串的长度 current_length = 0 # 当前数字子串的长度 current_number = &#39;&#39; # 当前遍历的数字子串 max_numbers = [] # 存储所有最长的数字子串 for char in s: if char.isdigit(): # 如果当前字符是数字 current_number += char # 将当前数字加到当前数字子串 current_length += 1 # 当前数字子串的长度加1 if current_length &gt; max_length: # 如果当前数字子串长度超过了之前的最长长度 max_length = current_length # 更新最长数字子串的长度 max_numbers = [current_number] # 更新最长数字子串列表 elif current_length == max_length: # 如果当前数字子串长度等于最长长度 max_numbers.append(current_number) # 将当前数字子串加入到最长数字子串列表 else: # 如果当前字符不是数字 current_length = 0 # 重置当前数字子串的长度 current_number = &#39;&#39; # 重置当前数字子串 print(&#39;&#39;.join(max_numbers) + &#39;,&#39; + str(max_length)) # 输出所有最长的数字子串以及它们的长度 except EOFError: break</p><p>这段代码首先读取输入的字符串，然后逐个字符地遍历它。对于每个字符，如果它是数字，则更新当前数字子串和其长度；如果不是数字，则检查当前数字子串是否是最长的，如果是，则更新最长数字子串的记录；如果当前数字子串长度归零。最后，打印出所有最长的数字子串和它们的长度。</p><p>import re import sys</p><p>def get_longest_num_str(input_str):</p><h1 id="使用正则表达式分割字符串-得到所有数字子串的列表" tabindex="-1">使用正则表达式分割字符串，得到所有数字子串的列表 <a class="header-anchor" href="#使用正则表达式分割字符串-得到所有数字子串的列表" aria-label="Permalink to &quot;使用正则表达式分割字符串，得到所有数字子串的列表&quot;">​</a></h1><p>parts = re.split(r&#39;\\D+&#39;, input_str) max_length = 0 # 用于记录最长数字子串的长度 longest_parts = [] # 用于存储最长的数字子串</p><h1 id="遍历所有数字子串" tabindex="-1">遍历所有数字子串 <a class="header-anchor" href="#遍历所有数字子串" aria-label="Permalink to &quot;遍历所有数字子串&quot;">​</a></h1><p>for part in parts: if len(part) &gt; max_length: max_length = len(part) # 更新最长长度 longest_parts = [part] # 重新设置最长数字子串列表 elif len(part) == max_length and max_length != 0:</p><h1 id="如果当前字符串长度等于最长长度-则添加到列表中" tabindex="-1">如果当前字符串长度等于最长长度，则添加到列表中 <a class="header-anchor" href="#如果当前字符串长度等于最长长度-则添加到列表中" aria-label="Permalink to &quot;如果当前字符串长度等于最长长度，则添加到列表中&quot;">​</a></h1><p>longest_parts.append(part)</p><h1 id="将所有最长的数字子串合并为一个字符串-因为可能有多个相同长度的最长数字子串" tabindex="-1">将所有最长的数字子串合并为一个字符串，因为可能有多个相同长度的最长数字子串 <a class="header-anchor" href="#将所有最长的数字子串合并为一个字符串-因为可能有多个相同长度的最长数字子串" aria-label="Permalink to &quot;将所有最长的数字子串合并为一个字符串，因为可能有多个相同长度的最长数字子串&quot;">​</a></h1><p>result = &#39;&#39;.join(longest_parts)</p><h1 id="输出最长的数字子串和它的长度" tabindex="-1">输出最长的数字子串和它的长度 <a class="header-anchor" href="#输出最长的数字子串和它的长度" aria-label="Permalink to &quot;输出最长的数字子串和它的长度&quot;">​</a></h1><p>print(f&quot;{result},{max_length}&quot;)</p><h1 id="从标准输入读取多行" tabindex="-1">从标准输入读取多行 <a class="header-anchor" href="#从标准输入读取多行" aria-label="Permalink to &quot;从标准输入读取多行&quot;">​</a></h1><p>for line in sys.stdin: get_longest_num_str(line.strip()) # 使用strip去除每行的尾随空白字符</p></div>',1)])])}const d=t(s,[["render",o]]);export{c as __pageData,d as default};
